<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Bean Lab · Replica playground</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f3ed;color:#242a25;font:15px system-ui,sans-serif}header{background:#203b31;color:white;padding:25px 5vw;display:flex;justify-content:space-between;align-items:center}.brand{font-size:24px;font-weight:800}.tag{color:#bed4c5;font-size:13px}main{max-width:1320px;margin:auto;padding:35px 25px}h1{font-size:38px;letter-spacing:-1.5px;margin:0 0 12px}h2{font-size:20px;margin:0 0 18px}p{color:#677268;line-height:1.6}.intro{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:28px}.badge{padding:10px 16px;border-radius:30px;background:#dfebdd;color:#36573b;white-space:nowrap}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.card{background:white;border:1px solid #e1e4dc;border-radius:18px;padding:24px;margin-bottom:22px}.form-grid{display:grid;grid-template-columns:2fr 2fr 1fr auto;gap:14px;align-items:end}label{display:block;font-size:12px;color:#6b766e;margin-bottom:7px}select,input{width:100%;padding:12px;border:1px solid #dce2d9;border-radius:9px;background:#fafbf8;color:#25362a;font:inherit}button{background:#244b39;color:white;border:0;border-radius:9px;padding:13px 20px;cursor:pointer;font-weight:600}button:disabled{opacity:.5;cursor:wait}.count{font-size:36px;font-weight:750}.sub{color:#7b857c;font-size:12px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:#7c857e;font-weight:500}th,td{padding:11px 5px;border-bottom:1px solid #edf0e8}.pill{background:#f1f4ed;border-radius:5px;padding:4px 8px;font-size:11px}.new-row{background:#eff8dc}.catalog{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.product{background:#f8f7f1;border-radius:12px;padding:18px}.product strong{display:block;margin:10px 0}.price{font-size:20px;font-weight:700}.notice{min-height:30px;margin-top:12px;color:#244b39}.error{color:#a03333}footer{color:#798078;font-size:12px;padding:15px 0}.overflow{overflow:auto}@media(max-width:900px){.grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr 1fr}.catalog{grid-template-columns:repeat(2,1fr)}.intro{display:block}.badge{display:inline-block}h1{font-size:30px}}@media(max-width:500px){.form-grid,.catalog{grid-template-columns:1fr}main{padding:25px 14px}.card{padding:18px}}
</style></head><body>
<header><span class="brand">☕ Bean Lab</span><span class="tag">MYSQL REPLICATION PLAYGROUND</span></header>
<main><div class="intro"><div><h1>Один заказ. Две базы.</h1><p>Создайте заказ и наблюдайте, как он появляется на реплике.<br>Запись → primary. Чтение → replica. Автообновление каждые 2 секунды.</p></div><span class="badge" id="health" role="status">Подключаемся…</span></div>
<section class="card"><h2>Новый заказ</h2><form id="order-form"><div class="form-grid"><div><label for="customer">Покупатель</label><select name="customer_id" id="customer">@foreach($customers as $c)<option value="{{ $c->id }}">{{ $c->name }} · {{ $c->city }}</option>@endforeach</select></div><div><label for="product">Товар</label><select name="product_id" id="product">@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->name }} · {{ number_format($p->price / 100, 2) }} TJS</option>@endforeach</select></div><div><label for="quantity">Количество</label><input id="quantity" name="quantity" type="number" value="1" min="1" max="10" required></div><button id="create">Создать заказ →</button></div></form><div id="notice" class="notice" role="status" aria-live="polite"></div></section>
<div class="grid">@foreach(['writer'=>'Primary · запись','reader'=>'Replica · чтение'] as $key=>$title)<section class="card"><div class="head"><h2>{{ $title }}</h2><span class="pill">{{ $key === 'writer' ? 'mysql_writer' : 'mysql_reader' }}</span></div><span class="count" id="{{ $key }}-count">—</span><span class="sub"> заказов</span><div class="overflow"><table><thead><tr><th>Заказ</th><th>Покупатель</th><th>Сумма</th><th>Статус</th></tr></thead><tbody id="{{ $key }}-rows"></tbody></table></div></section>@endforeach</div>
<section class="card"><div class="head"><h2>Каталог кофейного магазина</h2><span class="sub">Цены в сомони · TJS</span></div><div class="catalog">@foreach($products as $p)<div class="product"><span class="sub">{{ $p->category }}</span><strong>{{ $p->name }}</strong><span class="price">{{ number_format($p->price / 100, 2) }}</span><span class="sub"> TJS</span><p>Остаток при загрузке: {{ $p->stock }} шт.</p></div>@endforeach</div></section><footer>Асинхронная репликация может успеть передать заказ до первого обновления экрана. Совпадение данных само по себе не измеряет задержку репликации.</footer></main>
<script>
const money=v=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2}).format(v/100);let lastOrder=null,refreshBusy=false;
function rows(target,orders){const body=document.getElementById(target+'-rows');body.replaceChildren();for(const o of orders){const tr=document.createElement('tr');if(o.id===lastOrder)tr.className='new-row';for(const value of ['#'+o.id,o.customer,money(o.total)+' TJS',({new:'Новый',paid:'Оплачен',shipped:'Отправлен',completed:'Завершён'})[o.status]||o.status]){const td=document.createElement('td');td.textContent=value;tr.append(td)}body.append(tr)}}
async function refresh(){if(refreshBusy)return;refreshBusy=true;try{const r=await fetch('/replica/snapshot',{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error('Не удалось прочитать базы');const s=await r.json();for(const key of ['writer','reader']){rows(key,s[key]);document.getElementById(key+'-count').textContent=s[key+'_count']}const equal=s.writer_count===s.reader_count&&JSON.stringify(s.writer)===JSON.stringify(s.reader);document.getElementById('health').textContent=equal?'Данные совпадают':'Наблюдается расхождение';if(lastOrder&&s.reader.some(o=>o.id===lastOrder)){document.getElementById('notice').textContent='Заказ #'+lastOrder+' виден на reader. Обновлено: '+new Date().toLocaleTimeString()}}catch(e){document.getElementById('health').textContent=e.message}finally{refreshBusy=false}}
document.getElementById('order-form').addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('create'),notice=document.getElementById('notice');button.disabled=true;notice.classList.remove('error');try{const r=await fetch('/replica/orders',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const data=await r.json();if(!r.ok)throw Error(data.message||'Не удалось создать заказ');lastOrder=data.id;notice.textContent='Заказ #'+lastOrder+' записан в primary. Ждём reader…';await refresh()}catch(err){notice.classList.add('error');notice.textContent=err.message}finally{button.disabled=false}});
refresh();setInterval(refresh,2000);
</script></body></html>
